import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { authApi } from '../api/authAPI';

export default function Login() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setError('');

    if (!username || !password) {
      setError('Vui lòng nhập đầy đủ thông tin đăng nhập.');
      return;
    }

    try {
      // Gọi API xác thực tài khoản từ bảng accounts
      const user = await authApi.login(username, password);

      if (!user) {
        setError('Tên đăng nhập hoặc mật khẩu không chính xác.');
        return;
      }

      // Kiểm tra trạng thái tài khoản (nếu bị khóa / inactive)
      if (user.status === 'inactive') {
        setError('Tai khoan da bi khoa');
        return;
      }

      // Lưu thông tin phiên đăng nhập vào localStorage
      localStorage.setItem('user', JSON.stringify(user));

      // Chuyển hướng đến trang danh sách môn học (/subject)
      navigate('/subject');

    } catch (err) {
      console.error('Login error:', err);
      setError('Đã xảy ra lỗi kết nối đến máy chủ.');
    }
  };

  return (
    <div style={{
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      height: '100vh',
      backgroundColor: '#f8f9fa'
    }}>
      <div style={{
        width: '400px',
        padding: '30px',
        borderRadius: '8px',
        boxShadow: '0 4px 12px rgba(0, 0, 0, 0.1)',
        backgroundColor: 'white'
      }}>
        <h2 style={{ textAlign: 'center', marginBottom: '25px', color: '#333' }}>Sign In</h2>
        
        {/* Hiển thị lỗi màu đỏ nếu có */}
        {error && (
          <p style={{ color: 'red', fontSize: '14px', textAlign: 'center', fontWeight: 'bold', marginBottom: '15px' }}>
            {error}
          </p>
        )}

        <form onSubmit={handleLogin}>
          <div style={{ marginBottom: '15px' }}>
            <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold', fontSize: '14px' }}>Email / Username</label>
            <input
              type="text"
              placeholder="email of student or lecture"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              style={{
                width: '100%',
                padding: '10px',
                borderRadius: '4px',
                border: '1px solid #ccc',
                boxSizing: 'border-box'
              }}
            />
          </div>

          <div style={{ marginBottom: '20px' }}>
            <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold', fontSize: '14px' }}>Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{
                width: '100%',
                padding: '10px',
                borderRadius: '4px',
                border: '1px solid #ccc',
                boxSizing: 'border-box'
              }}
            />
          </div>

          <button
            type="submit"
            style={{
              width: '100%',
              padding: '10px',
              backgroundColor: '#007bff',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              fontWeight: 'bold',
              cursor: 'pointer',
              fontSize: '16px'
            }}
          >
            Login
          </button>
        </form>
      </div>
    </div>
  );
}
